"""Fail-closed reconciliation for Kraken Spot execution.

No local state is treated as authoritative. Exchange responses are the source of
truth for order state, and mismatches block further live execution.
"""
from __future__ import annotations

from dataclasses import dataclass
from decimal import Decimal


@dataclass(frozen=True)
class ReconciliationResult:
    ok: bool
    reason: str
    order_id: str | None = None
    status: str | None = None
    executed_volume: Decimal = Decimal("0")
    remaining_volume: Decimal = Decimal("0")


class KrakenReconciler:
    TERMINAL = {"closed", "canceled", "expired", "rejected"}

    def __init__(self, broker):
        self.broker = broker

    def order(self, txid: str, *, expected_volume: Decimal | None = None) -> ReconciliationResult:
        if not txid:
            return ReconciliationResult(False, "missing_exchange_order_id")

        result = self.broker.query_orders(txid)
        orders = result.get("orders") or {}
        raw = orders.get(txid)

        # Kraken may return a single key even when the requested identifier is
        # represented in a normalized form. Never accept an unrelated order.
        if raw is None and len(orders) == 1:
            candidate_id, candidate = next(iter(orders.items()))
            if candidate_id == txid:
                raw = candidate

        if not isinstance(raw, dict):
            return ReconciliationResult(False, "exchange_order_not_found", txid)

        status = str(raw.get("status", "")).lower()
        if not status:
            return ReconciliationResult(False, "exchange_order_status_missing", txid)

        try:
            executed = Decimal(str(raw.get("vol_exec", "0")))
            remaining = Decimal(str(raw.get("vol", "0"))) - executed
        except Exception:
            return ReconciliationResult(False, "invalid_exchange_volume", txid)

        if executed < 0 or remaining < 0:
            return ReconciliationResult(False, "invalid_exchange_volume", txid, status)

        if expected_volume is not None and executed > Decimal(str(expected_volume)):
            return ReconciliationResult(False, "executed_volume_exceeds_intent", txid, status, executed, remaining)

        if status not in self.TERMINAL:
            return ReconciliationResult(True, "order_open", txid, status, executed, remaining)

        return ReconciliationResult(True, "order_reconciled", txid, status, executed, remaining)

    def open_orders_snapshot(self):
        result = self.broker.open_orders()
        orders = result.get("open") or {}
        if not isinstance(orders, dict):
            raise RuntimeError("invalid_open_orders_response")
        return orders

import unittest,os
from astra.execution.gates import GateState
from astra.execution.kraken import KrakenConfig,KrakenSpot,KrakenError
from astra.risk import RiskGuardian
class SafetyTests(unittest.TestCase):
 def test_all_gates_required(self):
  self.assertFalse(GateState(True,True,True,True,True,True,True,False).authorize())
  self.assertTrue(GateState(True,True,True,True,True,True,True,True).authorize())
 def test_default_off(self):
  os.environ.pop("ASTRA_LIVE_TRADING",None); self.assertFalse(KrakenConfig.from_env().live_enabled)
 def test_live_missing_credentials_blocked(self):
  with self.assertRaises(KrakenError): KrakenSpot(KrakenConfig(live_enabled=True))
 def test_risk_halts(self):
  r=RiskGuardian(); r.reset_day(100); self.assertTrue(r.observe(98)["halted"]); self.assertEqual(r.observe(98)["reason"], "daily_loss_limit")
if __name__=="__main__":unittest.main()

import unittest
from decimal import Decimal
from astra.execution.live import LiveExecutionError, LiveExecutionService
from astra.execution.reconciliation import KrakenReconciler


class FakeGate:
    def __init__(self, allowed=True):
        self.allowed = allowed

    def authorize(self):
        return self.allowed


class FakeBroker:
    def __init__(self, txid="OID-1"):
        self.txid = txid

    def submit_if_authorized(self, gate, **order):
        if not gate.authorize():
            return {"submitted": False, "mode": "LIVE_BLOCKED"}
        return {"submitted": True, "mode": "LIVE_SPOT", "result": {"txid": [self.txid]}}

    def query_orders(self, txid):
        return {"orders": {txid: {"status": "closed", "vol": "0.001", "vol_exec": "0.001"}}}

    def open_orders(self):
        return {"open": {}}


class LiveExecutionTests(unittest.TestCase):
    def test_human_approval_required(self):
        service = LiveExecutionService(FakeBroker(), FakeGate())
        with self.assertRaisesRegex(LiveExecutionError, "human approval"):
            service.submit(
                symbol="XBTUSD", side="buy", quantity=Decimal("0.001"),
                strategy_id="test", signal_timestamp="2026-01-01T00:00:00+00:00",
                human_approval=False,
            )

    def test_gate_required(self):
        service = LiveExecutionService(FakeBroker(), FakeGate(False))
        with self.assertRaisesRegex(LiveExecutionError, "gate denied"):
            service.submit(
                symbol="XBTUSD", side="buy", quantity=Decimal("0.001"),
                strategy_id="test", signal_timestamp="2026-01-01T00:00:00+00:00",
                human_approval=True,
            )

    def test_duplicate_intent_blocked(self):
        service = LiveExecutionService(FakeBroker(), FakeGate())
        kwargs = dict(
            symbol="XBTUSD", side="buy", quantity=Decimal("0.001"),
            strategy_id="test", signal_timestamp="2026-01-01T00:00:00+00:00",
            human_approval=True,
        )
        first = service.submit(**kwargs)
        self.assertEqual(first["exchange_order_id"], "OID-1")
        with self.assertRaisesRegex(LiveExecutionError, "duplicate"):
            service.submit(**kwargs)

    def test_reconciliation_uses_exchange_truth(self):
        reconciler = KrakenReconciler(FakeBroker())
        result = reconciler.order("OID-1", expected_volume=Decimal("0.001"))
        self.assertTrue(result.ok)
        self.assertEqual(result.status, "closed")
        self.assertEqual(result.executed_volume, Decimal("0.001"))


if __name__ == "__main__":
    unittest.main()

def long_momentum(bars, window=30, threshold=0.0):
    closes=[b.close for b in bars]; out=[]
    for i,p in enumerate(closes):
        out.append(0 if i < window else int(p/closes[i-window]-1 > threshold/100))
    return out

from dataclasses import dataclass

@dataclass(frozen=True)
class Bar:
    t: int
    close: float

def backtest_signals(bars, signals, fee=0.0005, slip=0.0002):
    if len(bars) != len(signals): raise ValueError("signals length must match bars")
    equity=1.0; pos=0; peak=1.0; maxdd=0.0; trades=0
    for i,b in enumerate(bars):
        if i: equity *= 1 + pos*(b.close/bars[i-1].close-1)
        target=max(0,min(1,int(signals[i])))
        if target != pos:
            equity *= max(0,1-abs(target-pos)*(fee+slip)); trades+=1; pos=target
        peak=max(peak,equity); maxdd=max(maxdd,1-equity/peak)
    return {"return_pct":round((equity-1)*100,6),"max_drawdown_pct":round(maxdd*100,6),"trades":trades}

from dataclasses import dataclass
import math

@dataclass(frozen=True)
class RiskLimits:
    max_position: float=1.0
    max_daily_loss: float=0.02
    max_drawdown: float=0.08

class RiskGuardian:
    def __init__(self, limits=RiskLimits()):
        self.limits=limits; self.day_start=1.0; self.peak=1.0; self.halted=False; self.reason=None
    def reset_day(self,equity):
        self.day_start=float(equity); self.peak=float(equity); self.halted=False; self.reason=None
    def observe(self,equity):
        equity=float(equity)
        if not math.isfinite(equity) or equity < 0: raise ValueError("invalid equity")
        self.peak=max(self.peak,equity)
        daily=(self.day_start-equity)/self.day_start if self.day_start else 0
        dd=(self.peak-equity)/self.peak if self.peak else 0
        if daily >= self.limits.max_daily_loss: self.halted=True; self.reason="daily_loss_limit"
        if dd >= self.limits.max_drawdown: self.halted=True; self.reason="max_drawdown_limit"
        return {"halted":self.halted,"reason":self.reason,"daily_loss":daily,"drawdown":dd}
    def authorize(self,target):
        if self.halted:return 0.0
        return max(-self.limits.max_position,min(self.limits.max_position,float(target)))

from dataclasses import dataclass

@dataclass
class KillSwitch:
    halted: bool=False
    reason: str|None=None
    def trip(self,reason): self.halted=True; self.reason=str(reason)
    def authorize(self): return not self.halted

class ExecutionGate:
    def __init__(self,kill_switch): self.kill_switch=kill_switch
    def authorize(self,*,data_valid,strategy_valid,risk_valid,execution_valid,reconciliation_valid,human_approval,live_enabled):
        return bool(live_enabled and data_valid and strategy_valid and risk_valid and execution_valid and reconciliation_valid and human_approval and self.kill_switch.authorize())

from dataclasses import dataclass
@dataclass(frozen=True)
class GateState:
    data_valid: bool=False
    strategy_valid: bool=False
    risk_valid: bool=False
    execution_valid: bool=False
    reconciliation_valid: bool=False
    kill_switch_valid: bool=False
    human_approval: bool=False
    live_enabled: bool=False
    def authorize(self): return all((self.data_valid,self.strategy_valid,self.risk_valid,self.execution_valid,self.reconciliation_valid,self.kill_switch_valid,self.human_approval,self.live_enabled))
class LiveAuthorization:
    def __init__(self,state): self.state=state
    def authorize(self): return self.state.authorize()

from dataclasses import dataclass
import hashlib,json

@dataclass(frozen=True)
class OrderIntent:
    intent_id:str; symbol:str; side:str; quantity:str; strategy_id:str; signal_timestamp:str
    @staticmethod
    def create(*,symbol,side,quantity,strategy_id,signal_timestamp):
        d={"symbol":symbol.upper(),"side":side.lower(),"quantity":str(quantity),"strategy_id":strategy_id,"signal_timestamp":signal_timestamp}
        return OrderIntent("intent-"+hashlib.sha256(json.dumps(d,sort_keys=True,separators=(",",":")).encode()).hexdigest()[:24],**d)

class ExecutionLedger:
    def __init__(self): self.ids=set(); self.events=[]
    def register(self,intent):
        if intent.intent_id in self.ids:return False
        self.ids.add(intent.intent_id); self.events.append({"type":"intent_created","id":intent.intent_id}); return True
